import React, { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import "./suggestion.css";
import { translations } from "./translations";
import LanguageSelector from "./languageSelector.jsx";
import {
  Smile,
  Leaf,
  HeartPulse,
  Wind,
  Thermometer,
  Brain,
  Zap,
} from "lucide-react";

const iconMap = {
  fever: <Thermometer className="inline w-5 h-5 text-red-500" />,
  cough: <Wind className="inline w-5 h-5 text-blue-500" />,
  headache: <Brain className="inline w-5 h-5 text-purple-500" />,
  fatigue: <Zap className="inline w-5 h-5 text-yellow-500" />,
  chest_pain: <HeartPulse className="inline w-5 h-5 text-pink-500" />,
};

export default function SuggestionPage() {
  const location = useLocation();
  const navigate = useNavigate();
  const [lang, setLang] = useState("english");
  const [showLangPopup, setShowLangPopup] = useState(false);
  const [suggestions, setSuggestions] = useState([]);

  const { predictions = [], symptoms = [] } = location.state || {};

  const [language, setLanguage] = useState(
    () => localStorage.getItem("lang") || "en"
  );
  const langText = translations[language] || translations.en;

  // 🧠 fetch suggestions from backend
  useEffect(() => {
    if (symptoms.length > 0) {
      fetch("/api/suggestions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ symptoms, lang }),
      })
        .then((res) => res.json())
        .then((data) => setSuggestions(data.suggestions || []))
        .catch(() => setSuggestions([]));
    }
  }, [symptoms, lang]);

  // 🧩 handle language change
  const handleLangSelect = (selectedLang) => {
    setLang(selectedLang);
    setShowLangPopup(false);
  };

  return (
    <div className="suggestion-page">
      <div className="suggestion-container">
        {/* HEADER */}
        <div className="suggestion-header">
          <h1>💡 Health Suggestions</h1>
          <button onClick={() => setShowLangPopup(true)} className="lang-btn">
            {lang === "english" ? "English" : "Kriol"}
          </button>
        </div>

        {/* 🌐 LANGUAGE POPUP */}
        {showLangPopup && (
          <div
            className="popup-overlay"
            onClick={() => setShowLangPopup(false)}
          >
            <div
              className="popup-content"
              onClick={(e) => e.stopPropagation()} // prevent overlay click
            >
              <h3 className="popup-title">Choose Language</h3>
              <div className="popup-options">
                <button
                  className={`popup-option ${
                    lang === "english" ? "selected" : ""
                  }`}
                  onClick={() => handleLangSelect("english")}
                >
                  🇬🇧 English
                </button>
                <button
                  className={`popup-option ${
                    lang === "kriol" ? "selected" : ""
                  }`}
                  onClick={() => handleLangSelect("kriol")}
                >
                  🇦🇺 Kriol
                </button>
              </div>
            </div>
          </div>
        )}

        {/* ✅ Possible Conditions */}
        <section>
          <h2 className="section-title">❤️ Possible Conditions</h2>
          <ul className="condition-list">
            {predictions.map((p, i) => (
              <li key={i}>
                {p.disease} – confidence: {(p.score * 100).toFixed(0)}%
                <div className="progress-bar">
                  <div
                    className="progress-fill"
                    style={{ width: `${p.score * 100}%` }}
                  ></div>
                </div>
              </li>
            ))}
          </ul>
        </section>

        {/* 😊 Symptoms */}
        <section>
          <h2 className="section-title">😊 Symptoms You Mentioned</h2>
          {symptoms.map((s, i) => (
            <div key={i} className="suggestion-card">
              <p>
                {iconMap[s] || "•"} {s}
              </p>
            </div>
          ))}
        </section>

        {/* 🌿 What You Can Do */}
        <section>
          <h2 className="section-title">🌿 What You Can Do Now</h2>
          {suggestions.map((item, i) => (
            <div key={i} className="suggestion-card">
              <p className="font-bold text-lg capitalize">{item.symptom}</p>
              <p>
                <strong>Description:</strong> {item.description}
              </p>
              <p>
                <strong>Common Causes:</strong> {item.common_causes}
              </p>
              <p>
                <strong>Advice:</strong> {item.advice}
              </p>
            </div>
          ))}
        </section>

        {/* FOOTER */}
        <div className="footer-buttons no-print">
          <button onClick={() => navigate(-1)} className="btn-secondary">
            ← Back
          </button>
        </div>
      </div>
    </div>
  );
}
